# Parse map
DB='/data/maps/e2e_test_case_0.Civ6Map'
conn=sqlite3.connect(DB)
cur=conn.cursor()
cur.execute('SELECT Width, Height, WrapX, WrapY FROM Map')
width, height, wrapx, wrapy = cur.fetchone()
wrapx = bool(wrapx)
wrapy = bool(wrapy)
cur.execute('SELECT ID, TerrainType FROM Plots')
plots = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, FeatureType FROM PlotFeatures')
features = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, ResourceType, ResourceCount FROM PlotResources')
resources = {row[0]: row[1] for row in cur.fetchall()}
cur.execute('SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers')
river_rows = {row[0]: (bool(row[1]), bool(row[2]), bool(row[3])) for row in cur.fetchall()}

strategic_resources = {
    'RESOURCE_IRON','RESOURCE_HORSES','RESOURCE_NITER','RESOURCE_COAL',
    'RESOURCE_OIL','RESOURCE_ALUMINUM','RESOURCE_URANIUM'
}
luxury_resources = {
    'RESOURCE_DIAMONDS','RESOURCE_GOLD','RESOURCE_SILVER','RESOURCE_GEMS','RESOURCE_JADE',
    'RESOURCE_AMBER','RESOURCE_PEARLS','RESOURCE_WHALES','RESOURCE_WINE','RESOURCE_SALT',
    'RESOURCE_TRUFFLES','RESOURCE_SPICES','RESOURCE_SILK','RESOURCE_MARBLE',
    'RESOURCE_IVORY','RESOURCE_COTTON','RESOURCE_CITRUS','RESOURCE_COFFEE','RESOURCE_SUGAR',
    'RESOURCE_TOBACCO','RESOURCE_DYES','RESOURCE_OLIVES','RESOURCE_FURS','RESOURCE_INCENSE',
    'RESOURCE_TEA','RESOURCE_TURTLES','RESOURCE_CLOVES','RESOURCE_COCOA','RESOURCE_PERFUME'
}

def simplify_terrain(t):
    if t is None:
        return None
    if 'MOUNTAIN' in t:
        return 'MOUNTAIN'
    if 'OCEAN' in t:
        return 'OCEAN'
    if 'COAST' in t:
        return 'COAST'
    if 'LAKE' in t:
        return 'LAKE'
    if 'GRASS' in t:
        return 'GRASS'
    if 'PLAINS' in t:
        return 'PLAINS'
    if 'DESERT' in t:
        return 'DESERT'
    if 'TUNDRA' in t:
        return 'TUNDRA'
    if 'SNOW' in t:
        return 'SNOW'
    return t


def in_bounds(x,y):
    return 0<=x<width and 0<=y<height


def neighbor_coord(x,y,d):
    nx, ny = get_neighbor_at_direction(x,y,d)
    if wrapx:
        nx %= width
    if wrapy:
        ny %= height
    if not in_bounds(nx, ny):
        return None
    return (nx, ny)

# River edges per tile
river_edges_by_id = defaultdict(list)
for pid in plots:
    x = pid % width
    y = pid // width
    ne, w, nw = river_rows.get(pid, (False, False, False))
    edges=[]
    if ne: edges.append(1)
    if nw: edges.append(2)
    if w: edges.append(3)
    # E from neighbor W
    n = neighbor_coord(x,y,0)
    if n:
        nid = n[1]*width + n[0]
        if river_rows.get(nid, (False, False, False))[1]:
            edges.append(0)
    # SW from neighbor NE
    n = neighbor_coord(x,y,4)
    if n:
        nid = n[1]*width + n[0]
        if river_rows.get(nid, (False, False, False))[0]:
            edges.append(4)
    # SE from neighbor NW
    n = neighbor_coord(x,y,5)
    if n:
        nid = n[1]*width + n[0]
        if river_rows.get(nid, (False, False, False))[2]:
            edges.append(5)
    river_edges_by_id[pid] = edges

# Build tiles
tiles = {}
for pid, terrain in plots.items():
    x=pid%width; y=pid//width
    feature = features.get(pid)
    res = resources.get(pid)
    res_type = None
    if res:
        if res in strategic_resources:
            res_type='STRATEGIC'
        elif res in luxury_resources:
            res_type='LUXURY'
        else:
            res_type='BONUS'
    tiles[(x,y)] = Tile(
        x=x,y=y,
        terrain=simplify_terrain(terrain),
        feature=feature,
        is_hills=('HILLS' in (terrain or '')),
        is_floodplains=bool(feature and 'FLOODPLAINS' in feature),
        river_edges=river_edges_by_id.get(pid, []),
        river_names=[],
        resource=res,
        resource_type=res_type,
        improvement=None,
    )

# Candidate city centers near key features
key_features = [(21,13),(20,14),(22,11),(21,15),(20,13),(20,15),(23,11),(24,12),(23,13),(23,14),(23,15),(23,16),(22,17)]
city_candidates=[]
for (x,y), tile in tiles.items():
    if tile.is_water or tile.is_mountain or tile.is_natural_wonder:
        continue
    if any(hex_distance(x,y,kx,ky)<=2 for kx,ky in key_features):
        city_candidates.append((x,y))
# Score by adjacency potential near features

def city_score(cx,cy):
    score=0
    for (x,y), tile in tiles.items():
        if hex_distance(cx,cy,x,y)>2:
            continue
        if tile.feature=='FEATURE_GEOTHERMAL_FISSURE':
            score+=4
        if tile.feature=='FEATURE_REEF':
            score+=4
        if tile.is_mountain:
            score+=2
        if tile.feature=='FEATURE_JUNGLE':
            score+=1
        if tile.feature=='FEATURE_FOREST':
            score+=1
    return score

city_candidates = sorted(set(city_candidates), key=lambda c: city_score(*c), reverse=True)[:12]
print('city candidates', city_candidates)

population=9
max_specialty=placement_rules.calculate_max_specialty_districts(population)

SPECIALTY_TYPES=[DistrictType.CAMPUS, DistrictType.COMMERCIAL_HUB, DistrictType.INDUSTRIAL_ZONE, DistrictType.HOLY_SITE, DistrictType.HARBOR, DistrictType.THEATER_SQUARE]
SUPPORT_TYPES=[DistrictType.AQUEDUCT, DistrictType.DAM, DistrictType.CANAL]
TOP_K=4

best=None

for city_center in city_candidates:
    rules = get_placement_rules(tiles, city_center, population)
    base = {city_center: DistrictType.CITY_CENTER}
    calc = get_adjacency_calculator(tiles)

    candidates={}
    for dt in SPECIALTY_TYPES:
        coords=[]
        for (x,y), tile in tiles.items():
            if (x,y)==city_center:
                continue
            if hex_distance(city_center[0], city_center[1], x,y)>3:
                continue
            if rules.validate_placement(dt, x,y, base).valid:
                coords.append((x,y))
        # score base adjacency
        scored=[]
        for c in coords:
            placements=dict(base)
            placements[c]=dt
            total, per = calc.calculate_total_adjacency(placements)
            adj = 0
            for key,res in per.items():
                if key.startswith(dt.name+'@'):
                    adj = res.total_bonus
                    break
            scored.append((c, adj))
        scored.sort(key=lambda t:t[1], reverse=True)
        candidates[dt]=[c for c,_ in scored[:TOP_K]]

    support_candidates={}
    for dt in SUPPORT_TYPES:
        coords=[]
        for (x,y), tile in tiles.items():
            if (x,y)==city_center:
                continue
            if hex_distance(city_center[0], city_center[1], x,y)>3:
                continue
            if rules.validate_placement(dt, x,y, base).valid:
                coords.append((x,y))
        support_candidates[dt]=coords

    available=[dt for dt in SPECIALTY_TYPES if candidates[dt]]
    for r in range(1, max_specialty+1):
        for dt_subset in itertools.combinations(available, r):
            coord_lists=[candidates[dt] for dt in dt_subset]
            if any(len(lst)==0 for lst in coord_lists):
                continue
            for coords_choice in itertools.product(*coord_lists):
                if len(set(coords_choice)) != len(coords_choice):
                    continue
                placements=dict(base)
                for dt,c in zip(dt_subset, coords_choice):
                    placements[c]=dt
                # support choices (at most one per type)
                support_opts=[]
                for sdt in SUPPORT_TYPES:
                    opts=[None]
                    for c in support_candidates[sdt]:
                        if c in placements:
                            continue
                        if rules.validate_placement(sdt, c[0], c[1], placements).valid:
                            opts.append(c)
                    support_opts.append(opts)
                for support_choice in itertools.product(*support_opts):
                    full=dict(placements)
                    overlap=False
                    for sdt,c in zip(SUPPORT_TYPES, support_choice):
                        if c is None:
                            continue
                        if c in full:
                            overlap=True
                            break
                        full[c]=sdt
                    if overlap:
                        continue
                    total, per = calc.calculate_total_adjacency(full)
                    if best is None or total > best['total']:
                        best = {'total': total, 'city_center': city_center, 'placements': full, 'per': per}

print('best total', best['total'])
print('city', best['city_center'])
print('placements', best['placements'])
print('per', {k:v.total_bonus for k,v in best['per'].items()})
